import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import AxeBuilder from "@axe-core/playwright";
import { expect, type Page } from "@playwright/test";

/**
 * Shared by the end-to-end tests. The demo users' sign-in values are read from the environment
 * (TXRISK_DEMO_SIGNIN_ANALYST and the like, generated by CI or kept in the gitignored
 * keycloak.env); this repository holds none.
 */

export type Who = "analyst" | "supervisor" | "admin";

export const AUTH_DIR = resolve(__dirname, ".auth");
export const stateFile = (who: Who) => resolve(AUTH_DIR, `${who}.json`);

export function signInValueFor(who: Who): string {
  const name = `TXRISK_DEMO_SIGNIN_${who.toUpperCase()}`;
  const value = process.env[name];
  if (!value) {
    throw new Error(`${name} is not set: load keycloak.env into the environment (see README)`);
  }
  return value;
}

/** What the global setup learned and seeded. */
export type Seeded = {
  analystId: string;
  /** Added to every seeded Wallet name after its tag, e.g. `w-e2ew<suffix>-m0`. */
  suffix: string;
  cases: Record<string, { case_id: number; wallet_id: string }[]>;
};

export function seeded(): Seeded {
  return JSON.parse(readFileSync(resolve(AUTH_DIR, "seeded.json"), "utf8")) as Seeded;
}

/** Signs in through Keycloak's own page, as the demo user of that role. */
export async function signIn(page: Page, who: Who): Promise<void> {
  await page.goto("/");
  await page.getByRole("link", { name: "Sign in" }).click();
  await page.locator("#username").fill(`demo-${who}`);
  await page.locator("#password").fill(signInValueFor(who));
  await page.locator("#kc-login").click();
  await page.waitForURL(/localhost:3000/);
}

/** No WCAG A or AA violation that axe can detect on the page as it is now. */
export async function expectAccessible(page: Page): Promise<void> {
  const results = await new AxeBuilder({ page })
    .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa"])
    .analyze();
  expect(results.violations.map((v) => `${v.id}: ${v.help} (${v.nodes.length})`)).toEqual([]);
}
